import { checkSend } from process.argv[2];
EOF
cat > /tmp/gt/t.mjs <<'EOF'
const { checkSend } = await import(process.argv[2]);
const U = (o={}) => ({ id:"u", timeZone:"America/Chicago", sms:{ optedIn:true, optedOutAt:null }, ...o });
const M = { kind:"marketing", text:"Sale today! Reply STOP to opt out." };
const T = { kind:"transactional", text:"Your code is 123456" };
const d = (s) => new Date(s);
let bad = 0;
const t = (name, got, rule, allowed = rule === "") => {
  const ok = got.allowed === allowed && got.rule === rule;
  if (!ok) bad++;
  console.log(ok ? "ok  " : "FAIL", name, JSON.stringify(got));
};
// Chicago CDT = UTC-5 in Oct, CST = UTC-6 in Dec
t("chicago 14:00 CDT", await checkSend({user:U(),message:M,now:d("2026-10-23T19:00:00Z")}), "");
t("chicago 07:59 CDT", await checkSend({user:U(),message:M,now:d("2026-10-23T12:59:00Z")}), "quiet-hours");
t("chicago 08:00 CDT", await checkSend({user:U(),message:M,now:d("2026-10-23T13:00:00Z")}), "");
t("chicago 20:59 CDT", await checkSend({user:U(),message:M,now:d("2026-10-24T01:59:00Z")}), "");
t("chicago 21:00 CDT", await checkSend({user:U(),message:M,now:d("2026-10-24T02:00:00Z")}), "quiet-hours");
t("chicago 20:30 CST winter", await checkSend({user:U(),message:M,now:d("2026-12-15T02:30:00Z")}), "");
t("chicago 21:30 CST winter", await checkSend({user:U(),message:M,now:d("2026-12-15T03:30:00Z")}), "quiet-hours");
// DST: 2026-11-01 fall back; 07:30 CST = 13:30Z
t("dst day 07:30 CST", await checkSend({user:U(),message:M,now:d("2026-11-01T13:30:00Z")}), "quiet-hours");
t("tokyo 10:00", await checkSend({user:U({timeZone:"Asia/Tokyo"}),message:M,now:d("2026-10-23T01:00:00Z")}), "");
t("tokyo 03:00 (UTC afternoon)", await checkSend({user:U({timeZone:"Asia/Tokyo"}),message:M,now:d("2026-10-22T18:00:00Z")}), "quiet-hours");
t("kolkata 22:00", await checkSend({user:U({timeZone:"Asia/Kolkata"}),message:M,now:d("2026-10-23T16:30:00Z")}), "quiet-hours");
t("midnight UTC-> chicago 19:00", await checkSend({user:U(),message:M,now:d("2026-10-24T00:00:00Z")}), "");
t("null tz marketing", await checkSend({user:U({timeZone:null}),message:M,now:d("2026-10-23T19:00:00Z")}), "unknown-time-zone");
t("bad tz marketing", await checkSend({user:U({timeZone:"Mars/Base"}),message:M,now:d("2026-10-23T19:00:00Z")}), "unknown-time-zone");
t("UTC tz marketing", await checkSend({user:U({timeZone:"UTC"}),message:M,now:d("2026-10-23T19:00:00Z")}), "unknown-time-zone");
t("tz transactional null at 3am", await checkSend({user:U({timeZone:null}),message:T,now:d("2026-10-23T08:00:00Z")}), "");
t("tz transactional chicago 3am", await checkSend({user:U(),message:T,now:d("2026-10-23T08:00:00Z")}), "");
t("no consent mkt", await checkSend({user:U({sms:{optedIn:false,optedOutAt:null}}),message:M,now:d("2026-10-23T19:00:00Z")}), "no-consent");
t("no consent txn ok", await checkSend({user:U({sms:{optedIn:false,optedOutAt:null}}),message:T,now:d("2026-10-23T19:00:00Z")}), "");
t("opted out mkt", await checkSend({user:U({sms:{optedIn:true,optedOutAt:"2026-10-01T00:00:00Z"}}),message:M,now:d("2026-10-23T19:00:00Z")}), "opted-out");
t("opted out txn", await checkSend({user:U({sms:{optedIn:true,optedOutAt:"2026-10-01T00:00:00Z"}}),message:T,now:d("2026-10-23T19:00:00Z")}), "opted-out");
t("opted out garbage", await checkSend({user:U({sms:{optedIn:true,optedOutAt:"garbage"}}),message:M,now:d("2026-10-23T19:00:00Z")}), "opted-out");
t("no opt-out notice", await checkSend({user:U(),message:{kind:"marketing",text:"Sale today!"},now:d("2026-10-23T19:00:00Z")}), "no-opt-out-notice");
t("text 'Text STOP'", await checkSend({user:U(),message:{kind:"marketing",text:"Sale! Text STOP to end"},now:d("2026-10-23T19:00:00Z")}), "");
// odd input never throws
for (const [n, a] of Object.entries({
  none: undefined, null: null, empty: {}, nowStr: {user:U(),message:M,now:"x"}, nowBad:{user:U(),message:M,now:new Date("x")},
  userNull:{user:null,message:M,now:new Date()}, msgNull:{user:U(),message:null,now:new Date()},
  kind:{user:U(),message:{kind:"x",text:"a"},now:new Date()}, text:{user:U(),message:{kind:"marketing",text:5},now:new Date()},
  smsMissing:{user:{id:"1"},message:M,now:new Date()}, tzNum:{user:U({timeZone:5}),message:M,now:new Date()},
  getter:{user:{get sms(){throw new Error("boom")}},message:M,now:new Date()},
})) {
  try { const r = await checkSend(a); const ok = r.allowed===false && typeof r.rule==="string" && r.rule; if(!ok) bad++; console.log(ok?"ok  ":"FAIL","odd "+n,JSON.stringify(r)); }
  catch(e){ bad++; console.log("FAIL threw",n,e.message); }
}
console.log(bad ? `${bad} FAILED` : "ALL PASS");
EOF
node /tmp/gt/t.mjs "$PWD/bot.mjs"

